        if m:
            val = m[-1].replace(",", "")
            return f"{float(val):.2f}"

    # Comma-as-decimal fallback: "9,90" at end (take last 1-3 digits , 2 digits)
    m = re.search(r"(?<![\w.])(\d{1,3}(?:[,\s]\d{3})*)[,](\d{2})(?![\w.\d])", line)
