    re.compile(r"\bGRAND\s*TOTAL\b"),
    re.compile(r"\bTOTAL\s*:?\s*RM\b"),
    re.compile(r"\bTOTAL\s*AMOUNT\b"),
    re.compile(
        r"\b(?:TOTAL\s+DUE|AMOUNT\s+DUE|BALANCE\s+DUE|NETT?\s+TOTAL|NET\s+TOTAL|TOTAL|AMOUNT)\b"
    ),
]


def extract_total(text):
    lines_r = [ln for ln in text.splitlines() if ln.strip()]
    lines_c = [canon(ln) for ln in lines_r]

    for tier_idx, pat in enumerate(TIER_PATTERNS):
        cands = tier_candidates(lines_c, lines_r, pat)
        if not cands:
            continue

        # Walk candidates from last to first (bottom of receipt is usually the final total)
        for i, c, r in reversed(cands):
            amt = find_amount_in_line(r)
            if amt is not None:
                # Reject one-decimal / zero-only values when a parent line has more
                return amt, (tier_idx, c, r)

            # Fallback: if this line has NO digits at all, consult next non-empty line
            if not re.search(r"\d", r):
                for j in range(i + 1, len(lines_r)):
                    nxt_c = lines_c[j]
                    nxt_r = lines_r[j]
