                    if any(
                        k in nxt_c
                        for k in (
                            "CASH", "TENDERED", "CHANGE", "VISA", "MASTER",
                            "CARD", "PAYMENT", "PAID", "RECEIVED", "CREDIT", "DEBIT",
                        )
                    ):
                        break
                    if is_excluded(nxt_c):
                        break
                    amt2 = find_amount_in_line(nxt_r)
                    if amt2 is not None:
                        return amt2, (tier_idx, c, nxt_r)
                    break
    return None, None


# ---------- Date extraction ----------

DATE_PATTERNS = [
    # strict dd/mm/yyyy, dd-mm-yyyy
    re.compile(r"(?<!\d)(\d{2})[/\-](\d{2})[/\-](\d{4})(?!\d)"),
    # dd/mm/yy, dd-mm-yy
    re.compile(r"(?<!\d)(\d{2})[/\-](\d{2})[/\-](\d{2})(?!\d)"),
]


def _try_date(d, m, y):
    try:
        d, m = int(d), int(m)
        y = int(y)
        if y < 100:
            y = 2000 + y
        if 1 <= d <= 31 and 1 <= m <= 12 and 2000 <= y <= 2099:
            # cheap calendar validity
            import datetime
            datetime.date(y, m, d)
            return f"{y:04d}-{m:02d}-{d:02d}"
    except Exception:
        pass
    return None


def extract_date(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    # Prefer lines containing DATE / DATA / DAIE
    labeled = []
    other = []
    for ln in lines:
        c = canon(ln)
        if re.search(r"\b(DATE|DATA|DAIE)\b", c) and not re.search(
            r"\b(PRINT|PRINTED|CLOSED|CLOSING)\b", c
        ):
            labeled.append(ln)
        else:
            other.append(ln)

    for group in (labeled, other):
        for ln in group:
            for pat in DATE_PATTERNS:
                for m in pat.finditer(ln):
                    iso = _try_date(*m.groups())
                    if iso:
                        return iso
    return None


# ---------- Multi-variant consensus ----------

def extract_from_image(path):
    texts = ocr_variants(path)
    totals = []
    dates = []
    for t in texts:
        tot, meta = extract_total(t)
        if tot:
            totals.append((tot, meta))
        d = extract_date(t)
        if d:
            dates.append(d)

    # Pick best total: prefer highest tier (lowest tier index), then most common value
    best_total = None
    if totals:
        # group by tier
        from collections import Counter
        by_tier = {}
        for val, meta in totals:
            tier_idx = meta[0]
            by_tier.setdefault(tier_idx, []).append(val)
        best_tier = min(by_tier)
        counts = Counter(by_tier[best_tier])
        best_total = counts.most_common(1)[0][0]

    # Pick best date: most common
    best_date = None
    if dates:
        from collections import Counter
        best_date = Counter(dates).most_common(1)[0][0]

    return best_date, best_total


# ---------- Main ----------

def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for f in files:
        path = os.path.join(IMG_DIR, f)
        try:
            d, t = extract_from_image(path)
        except Exception as e:
            print(f"ERROR {f}: {e}")
            d, t = None, None
        rows.append((f, d, t))
        print(f"{f}: date={d}  total={t}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in rows:
        ws.append([f, d, t])
    wb.save(OUT_PATH)
    print(f"Wrote {OUT_PATH}")


if __name__ == "__main__":
    main()
