        rows.append((f, d, t))
        print(f"{f}: date={d}  total={t}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in rows:
        ws.append([f, d, t])
    wb.save(OUT_PATH)
