{"command": "create", "file_text": """"Extract date and total_amount from each receipt image and write to xlsx."""
import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_PATH = "/app/workspace/stat_ocr.xlsx"


# ---------- OCR helpers ----------

def ocr_variants(path):
    """Return a list of OCR text strings from several preprocessing/PSM passes."""
    img = Image.open(path)
    gray = ImageOps.grayscale(img)
    scales = [
        ("1x", gray),
        ("2x", gray.resize((gray.width * 2, gray.height * 2), Image.LANCZOS)),
    ]
    texts = []
    for _, v in scales:
        for psm in ("--psm 6", "--psm 4"):
            try:
                texts.append(pytesseract.image_to_string(ImageOps.autocontrast(v), config=psm))
            except Exception:
                pass
    return texts


# ---------- Amount extraction ----------

MONEY_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])")
# Also allow space-split decimal "8 60" OR comma-as-decimal "9,90" repair later.

# Repair confusables inside amount-like tokens
CONFUSABLE = str.maketrans({
    "O": "0", "o": "0", "Q": "0", "u": "0",
    "l": "1", "I": "1", "|": "1",
    "S": "5", "s": "5",
    "B": "8",
    "Z": "2",
    "G": "6",
})


def find_amount_in_line(line):
    """Return a two-decimal amount string from `line` or None.

    Handles:
      - 1,234.56 and 1234.56
      - 9,90 (comma used as decimal separator; last token before line end)
      - 8 60 (space split between digits and cents)
    """
    # Standard regex first
    matches = MONEY_RE.findall(line)
    if matches:
        # pick the last monetary token
        val = matches[-1].replace(",", "")
        return f"{float(val):.2f}"

    # Try confusable repair on digit-dominant tokens near the end
    tokens = re.findall(r"[0-9OolI|SBZGQu.,\s]{3,}$", line)
    if tokens:
        rep = tokens[-1].translate(CONFUSABLE)
        m = MONEY_RE.findall(rep)
        if m:
            val = m[-1].replace(",", "")
            return f"{float(val):.2f}"

    # Comma-as-decimal fallback: "9,90" at end (take last 1-3 digits , 2 digits)
    m = re.search(r"(?<![\w.])(\d{1,3}(?:[,\s]\d{3})*)[,](\d{2})(?![\w.\d])", line)
    if m:
        whole = m.group(1).replace(",", "").replace(" ", "")
        return f"{float(whole + '.' + m.group(2)):.2f}"

    # Space-split decimal: "RM 8 60"
    m = re.search(r"(?<![\w.])(\d{1,3}(?:,\d{3})*)\s+(\d{2})(?![\w.\d])", line)
    if m:
        whole = m.group(1).replace(",", "")
        return f"{float(whole + '.' + m.group(2)):.2f}"

    return None


def canon(line):
    """Uppercase + collapse whitespace."""
    return re.sub(r"\s+", " ", line.upper()).strip()


# Exclusion check: is this line "really" a GST/TAX/SUBTOTAL/etc line?
EXCL_HARD = (
    "SUBTOTAL", "SUB TOTAL", "DISCOUNT", "CHANGE", "CASH TENDERED",
    "ROUNDING", "ROUNDING ADJ", "SST", "SST SUMMARY",
    "GST SUMMARY", "TAX SUMMARY", "TAX CODE", "GST ID", "GST NO",
    "GST REG", "SALES (EXCLUDING",  # "Total Sales (Excluding GST)"
    "EXCLUDING GST", "EXCL GST", "EXCL. GST", "EXCLUSIVE GST", "EXCLUSIVEGST",
    "EXC. TAX",
)


def is_excluded(c):
    if any(k in c for k in EXCL_HARD):
        return True
    # "Total GST" with nothing between: "TOTALGST" (after collapsing) or "TOTAL GST"
    if re.search(r"\bTOTAL\s*GST\b", c) and not re.search(
        r"\bTOTAL\s+(INCL|INCLUDES?|INCLUSIVE|SALES|AMOUNT|DUE)\b", c
    ):
        return True
    if re.search(r"\bTOTAL\s*TAX\b", c):
        return True
    if "GST 6%" in c and "TOTAL" not in c:
        return True
    if c.startswith("GST ") or c.startswith("TAX ") or c.startswith("SST "):
        return True
    # Qty labels
    if re.search(r"\bTOTAL\s*(QTY|QUANTITY|QUANTIT)\b", c):
        return True
    # "Amount(RM)" style column headers alone
    if re.fullmatch(r"[A-Z()%\s]+", c) and "RM" in c and not re.search(r"\d", c):
        return True
    return False


# Tier rules return a list of (canon_line, raw_line, index) sorted by original order
def tier_candidates(lines_c, lines_r, pattern):
    out = []
    for i, (c, r) in enumerate(zip(lines_c, lines_r)):
        if is_excluded(c):
            continue
        if pattern.search(c):
            out.append((i, c, r))
    return out


TIER_PATTERNS = [
    re.compile(r"\bGRAND\s*TOTAL\b"),
    re.compile(r"\bTOTAL\s*:?\s*RM\b"),
    re.compile(r"\bTOTAL\s*AMOUNT\b"),
    re.compile(
        r"\b(?:TOTAL\s+DUE|AMOUNT\s+DUE|BALANCE\s+DUE|NETT?\s+TOTAL|NET\s+TOTAL|TOTAL|AMOUNT)\b"
    ),
]


def extract_total(text):
    lines_r = [ln for ln in text.splitlines() if ln.strip()]
    lines_c = [canon(ln) for ln in lines_r]

    for tier_idx, pat in enumerate(TIER_PATTERNS):
        cands = tier_candidates(lines_c, lines_r, pat)
        if not cands:
            continue

        # Walk candidates from last to first (bottom of receipt is usually the final total)
        for i, c, r in reversed(cands):
            amt = find_amount_in_line(r)
            if amt is not None:
                # Reject one-decimal / zero-only values when a parent line has more
                return amt, (tier_idx, c, r)

            # Fallback: if this line has NO digits at all, consult next non-empty line
            if not re.search(r"\d", r):
                for j in range(i + 1, len(lines_r)):
                    nxt_c = lines_c[j]
                    nxt_r = lines_r[j]
                    # Exclude payment/tender/change lines
                    if any(
                        k in nxt_c
                        for k in (
                            "CASH", "TENDERED", "CHANGE", "VISA", "MASTER",
                            "CARD", "PAYMENT", "PAID", "RECEIVED", "CREDIT", "DEBIT",
                        )
                    ):
                        break
                    if is_excluded(nxt_c):
                        break
                    amt2 = find_amount_in_line(nxt_r)
                    if amt2 is not None:
                        return amt2, (tier_idx, c, nxt_r)
                    break
    return None, None


# ---------- Date extraction ----------

DATE_PATTERNS = [
    # strict dd/mm/yyyy, dd-mm-yyyy
    re.compile(r"(?<!\d)(\d{2})[/\-](\d{2})[/\-](\d{4})(?!\d)"),
    # dd/mm/yy, dd-mm-yy
    re.compile(r"(?<!\d)(\d{2})[/\-](\d{2})[/\-](\d{2})(?!\d)"),
]


def _try_date(d, m, y):
    try:
        d, m = int(d), int(m)
        y = int(y)
        if y < 100:
            y = 2000 + y
        if 1 <= d <= 31 and 1 <= m <= 12 and 2000 <= y <= 2099:
            # cheap calendar validity
            import datetime
            datetime.date(y, m, d)
            return f"{y:04d}-{m:02d}-{d:02d}"
    except Exception:
        pass
    return None


def extract_date(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    # Prefer lines containing DATE / DATA / DAIE
    labeled = []
    other = []
    for ln in lines:
        c = canon(ln)
        if re.search(r"\b(DATE|DATA|DAIE)\b", c) and not re.search(
            r"\b(PRINT|PRINTED|CLOSED|CLOSING)\b", c
        ):
            labeled.append(ln)
        else:
            other.append(ln)

    for group in (labeled, other):
        for ln in group:
            for pat in DATE_PATTERNS:
                for m in pat.finditer(ln):
                    iso = _try_date(*m.groups())
                    if iso:
                        return iso
    return None


# ---------- Multi-variant consensus ----------

def extract_from_image(path):
    texts = ocr_variants(path)
    totals = []
    dates = []
    for t in texts:
        tot, meta = extract_total(t)
        if tot:
            totals.append((tot, meta))
        d = extract_date(t)
        if d:
            dates.append(d)

    # Pick best total: prefer highest tier (lowest tier index), then most common value
    best_total = None
    if totals:
        # group by tier
        from collections import Counter
        by_tier = {}
        for val, meta in totals:
            tier_idx = meta[0]
            by_tier.setdefault(tier_idx, []).append(val)
        best_tier = min(by_tier)
        counts = Counter(by_tier[best_tier])
        best_total = counts.most_common(1)[0][0]

    # Pick best date: most common
    best_date = None
    if dates:
        from collections import Counter
        best_date = Counter(dates).most_common(1)[0][0]

    return best_date, best_total


# ---------- Main ----------

def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for f in files:
        path = os.path.join(IMG_DIR, f)
        try:
            d, t = extract_from_image(path)
        except Exception as e:
            print(f"ERROR {f}: {e}")
            d, t = None, None
        rows.append((f, d, t))
        print(f"{f}: date={d}  total={t}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in rows:
        ws.append([f, d, t])
    wb.save(OUT_PATH)
    print(f"Wrote {OUT_PATH}")


if __name__ == "__main__":
    main()
