        val = matches[-1].replace(",", "")
        return f"{float(val):.2f}"

    # Try confusable repair on digit-dominant tokens near the end
    tokens = re.findall(r"[0-9OolI|SBZGQu.,\s]{3,}$", line)
    if tokens:
